# LookML measure definition
view: orders {
  sql_table_name: `myproject.analytics.orders` ;;

  dimension: order_id {
    type: string
    primary_key: yes
    sql: ${TABLE}.order_id ;;
  }

  measure: total_revenue {
    type: sum
    sql: ${TABLE}.revenue_usd ;;
    value_format_name: usd
    description: "Total revenue from completed orders, excluding refunds"
    filters: [status: "completed"]
  }

  measure: order_count {
    type: count_distinct
    sql: ${order_id} ;;
  }
}

import (
    "log"
    cloudprofiler "cloud.google.com/go/profiler"
)

func main() {
    // Start Cloud Profiler — runs continuously in the background
    cfg := cloudprofiler.Config{
        Service:        "my-service",
        ServiceVersion: "v1.2.3",
        ProjectID:      "my-project",
        // Collect CPU and heap profiles
        MutexProfiling: true,
    }
    if err := cloudprofiler.Start(cfg); err != nil {
        log.Fatalf("profiler.Start: %v", err)
    }
    // ... rest of application startup
}
